1	import type { Customer } from "./policy.js";
2	
3	/**
4	 * Policy-wide modifiers: how the customer's relationship with the MHPCO
5	 * adjusts the policy base premium (the sum of all item base premiums).
6	 * Item-specific modifiers live with the items they affect.
7	 */
8	
9	/** Long-standing customers are rewarded with a loyalty discount. */
10	const LOYALTY_DISCOUNT_RATE = 0.2;
11	const LOYALTY_YEARS = 2;
12	
13	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
14	
15	function isLongStanding(customer: Customer): boolean {
16	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
17	}
18	
19	function loyaltyDiscount(
20	  customer: Customer,
21	  policyBasePremium: number,
22	): number {
23	  return isLongStanding(customer)
24	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
25	    : 0;
26	}
27	
28	/**
29	 * Every item in a quote is treated as a first insurance, regardless of
30	 * customer history, so this surcharge scales the policy base premium.
31	 */
32	function firstInsuranceSurcharge(policyBasePremium: number): number {
33	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
34	}
35	
36	/** Net adjustment the customer's history makes to the policy base premium. */
37	export function policyModifiers(
38	  customer: Customer,
39	  policyBasePremium: number,
40	): number {
41	  return (
42	    firstInsuranceSurcharge(policyBasePremium) -
43	    loyaltyDiscount(customer, policyBasePremium)
44	  );
45	}
