1	import type { Item, ItemPricing } from "./policy.js";
2	import { riskSurchargeOf } from "./risk-surcharge.js";
3	
4	/** The MHPCO price list for main items: base premium in G per item type. */
5	const MAIN_ITEM_BASE_PREMIUMS: Readonly<Record<string, number>> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	};
11	
12	function mainItemBasePremiumOf(item: Item): number {
13	  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
14	}
15	
16	/**
17	 * What one main item contributes: the price list's base premium, and the
18	 * item's own risk surcharges, which scale that same base premium.
19	 */
20	function priceMainItem(item: Item): ItemPricing {
21	  const basePremium = mainItemBasePremiumOf(item);
22	  return {
23	    basePremium,
24	    riskSurcharges: riskSurchargeOf(item, basePremium),
25	  };
26	}
27	
28	export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
29	  return mainItems.reduce<ItemPricing>(
30	    (total, item) => {
31	      const pricing = priceMainItem(item);
32	      return {
33	        basePremium: total.basePremium + pricing.basePremium,
34	        riskSurcharges: total.riskSurcharges + pricing.riskSurcharges,
35	      };
36	    },
37	    { basePremium: 0, riskSurcharges: 0 },
38	  );
39	}
