import { priceItems } from "./item-pricing.js";
import type { Customer, Item } from "./policy.js";
import {
  customerStandingDiscount,
  initialAssessmentSurcharge,
} from "./policy-modifier.js";

const PROCESSING_FEE = 5;

/**
 * Item-specific modifiers apply to the base premium of the affected item;
 * policy-wide modifiers apply to the policy base premium; the processing
 * fee is added at the very end.
 *
 * `previousContracts` is not read yet: the 15 % follow-up contract discount
 * is not an active behavior. Rounding is likewise not active, so a premium
 * may still come out as a fraction.
 */
export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  const { basePremium, riskSurcharges } = priceItems(items);

  return (
    basePremium +
    riskSurcharges +
    initialAssessmentSurcharge(basePremium) -
    customerStandingDiscount(customer, basePremium) +
    PROCESSING_FEE
  );
}

